    # ---------- 44. 夜雨寄北 ----------
    {
        "id": "li-shang-yin-44",
        "title": "夜雨寄北",
        "author": "李商隐",
        "poet_id": "li-shang-yin",
        "dynasty": "唐",
        "genre": "七言绝句",
        "year": "约大中二年（848）",
        "source": "《全唐诗·卷五三九》",
        "verse": [
            "君问归期未有期，巴山夜雨涨秋池。",
            "何当共剪西窗烛，却话巴山夜雨时。",
        ],
        "tijie": "此诗为李商隐滞留巴蜀、雨夜寄怀北方妻子之作，今昔回环，情致深婉，为唐人绝句中之缠绵名篇。",
        "notes": [
            ("寄北", "寄给北方（长安）的妻子。"),
            ("巴山", "泛指巴蜀山地。"),
            ("涨秋池", "夜雨使池水上涨。"),
            ("何当", "何时。"),
            ("剪烛", "剪去烛花使明。"),
            ("却话", "回头再说。"),
        ],
        "appreciation": "首句「君问归期未有期」以问答起，归期无定，怅惘已含；次句「巴山夜雨涨秋池」写眼前实景，夜雨涨池，孤寂弥深。后二句「何当共剪西窗烛，却话巴山夜雨时」由今夜推想他日团聚，共剪西窗之烛，再话今夜巴山夜雨——以未来之乐反衬今日之孤，且「巴山夜雨」首尾回环，时空交错，章法精巧。李商隐七绝擅长以情致胜，此篇尤见深婉绵邈，无一「思」字而思致无穷。",
        "famous": [
            ("何当共剪西窗烛，却话巴山夜雨时。", "缠绵名句，时空回环。"),
        ],
        "sources": [
            "《全唐诗》卷五三九",
            "《唐诗鉴赏辞典》李商隐条（上海辞书出版社，1983）",
        ],
    },
