    # ---------- 136. 碧城三首 ----------
    {
        "id": "li-shang-yin-136",
        "title": "碧城三首",
        "author": "李商隐",
        "poet_id": "li-shang-yin",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷131》",
        "verse": [
            "碧城十二曲阑干，犀辟尘埃玉辟寒。阆苑有书多附鹤，",
            "女床无树不栖鸾。星沈海底当窗见，雨过河源隔座看。",
            "若是晓珠明又定，一生长对水晶盘。",
            "对影闻声已可怜，玉池荷叶正田田。不逢萧史休回首，",
            "莫见洪崖又拍肩。紫凤放娇衔楚佩，赤鳞狂舞拨湘弦。",
            "鄂君怅望舟中夜，绣被焚香独自眠。",
            "七夕来时先有期，洞房帘箔至今垂。玉轮顾兔初生魄，",
            "铁网珊瑚未有枝。检与神方教驻景，收将凤纸写相思。",
            "武皇内传分明在，莫道人间总不知。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 137. 对雪二首 ----------
    {
        "id": "li-shang-yin-137",
        "title": "对雪二首",
        "author": "李商隐",
        "poet_id": "li-shang-yin",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷132》",
        "verse": [
            "寒气先侵玉女扉，清光旋透省郎闱。梅花大庾岭头发，",
            "柳絮章台街里飞。欲舞定随曹植马，有情应湿谢庄衣。",
            "龙山万里无多远，留待行人二月归。",
            "旋扑珠帘过粉墙，轻于柳絮重于霜。已随江令夸琼树，",
            "又入卢家妒玉堂。侵夜可能争桂魄，忍寒应欲试梅妆。",
            "关河冻合东西路，肠断斑骓送陆郎。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
