    # ---------- 147. 玉山 ----------
    {
        "id": "li-shang-yin-147",
        "title": "玉山",
        "author": "李商隐",
        "poet_id": "li-shang-yin",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷142》",
        "verse": [
            "玉山高与阆风齐，玉水清流不贮泥。何处更求回日驭，",
            "此中兼有上天梯。珠容百斛龙休睡，桐拂千寻凤要栖。",
            "闻道神仙有才子，赤箫吹罢好相携。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
