    # ---------- 188. 望喜驿别嘉陵江水二绝 ----------
    {
        "id": "li-shang-yin-188",
        "title": "望喜驿别嘉陵江水二绝",
        "author": "李商隐",
        "poet_id": "li-shang-yin",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷183》",
        "verse": [
            "嘉陵江水此东流，望喜楼中忆阆州。",
            "若到阆中还赴海，阆州应更有高楼。",
            "千里嘉陵江水色，含烟带月碧于蓝。",
            "今朝相送东流后，犹自驱车更向南。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 189. 别薛岩宾 ----------
    {
        "id": "li-shang-yin-189",
        "title": "别薛岩宾",
        "author": "李商隐",
        "poet_id": "li-shang-yin",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷184》",
        "verse": [
            "曙爽行将拂，晨清坐欲凌。别离真不那，风物正相仍。",
            "漫水任谁照，衰花浅自矜。还将两袖泪，同向一窗灯。",
            "桂树乖真隐，芸香是小惩。清规无以况，且用玉壶冰。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 190. 富平少侯 ----------
    {
        "id": "li-shang-yin-190",
        "title": "富平少侯",
        "author": "李商隐",
        "poet_id": "li-shang-yin",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷185》",
        "verse": [
            "七国三边未到忧，十三身袭富平侯。不收金弹抛林外，",
            "却惜银床在井头。彩树转灯珠错落，绣檀回枕玉雕锼。",
            "当关不报侵晨客，新得佳人字莫愁。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 191. 肠 ----------
    {
        "id": "li-shang-yin-191",
        "title": "肠",
        "author": "李商隐",
        "poet_id": "li-shang-yin",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷186》",
        "verse": [
            "有怀非惜恨，不奈寸肠何。即席回弥久，前时断固多。",
            "热应翻急烧，冷欲彻微波。隔树澌澌雨，通池点点荷。",
            "倦程山向背，望国阙嵯峨。故念飞书及，新欢借梦过。",
            "染筠休伴泪，绕雪莫追歌。拟问阳台事，年深楚语讹。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
