    # ---------- 325. 乐游原 ----------
    {
        "id": "li-shang-yin-325",
        "title": "乐游原",
        "author": "李商隐",
        "poet_id": "li-shang-yin",
        "dynasty": "唐",
        "genre": "五言绝句",
        "year": "约大中中",
        "source": "《全唐诗·卷五三九》",
        "verse": [
            "万树鸣蝉隔岸虹，乐游原上有西风。",
            "羲和自趁虞泉宿，不放斜阳更向东。",
        ],
        "tijie": "此诗写黄昏登乐游原之所见所感，以夕阳喻盛世将逝，含家国之忧与身世之慨，为唐人五绝中之晚唱。",
        "notes": [
            ("乐游原", "长安东南高地，登临胜地。"),
            ("向晚", "傍晚。"),
            ("意不适", "心情不畅。"),
            ("古原", "即乐游原。"),
        ],
        "appreciation": "首二句「向晚意不适，驱车登古原」叙事平易：日暮心闷，驱车登原散怀。后二句「夕阳无限好，只是近黄昏」为千古绝唱：夕阳之美无限，而黄昏将临，好景难久。此二句可作文人迟暮、盛世将倾之双重象征——李商隐处晚唐衰世，此叹亦含家国之忧。语极浅而意极深，以乐景写哀，余韵苍凉，为唐人五绝之晚唱绝调。",
        "famous": [
            ("夕阳无限好，只是近黄昏。", "晚唱名句，苍凉无尽。"),
        ],
        "sources": [
            "《全唐诗》卷五三九",
            "《唐诗鉴赏辞典》李商隐条（上海辞书出版社，1983）",
        ],
    },
