    # ---------- 416. 漫成五章 ----------
    {
        "id": "li-shang-yin-416",
        "title": "漫成五章",
        "author": "李商隐",
        "poet_id": "li-shang-yin",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷197》",
        "verse": [
            "沈宋裁辞矜变律，王杨落笔得良朋。",
            "当时自谓宗师妙，今日惟观对属能。",
            "李杜操持事略齐，三才万象共端倪。",
            "集仙殿与金銮殿，可是苍蝇惑曙鸡。",
            "生儿古有孙征虏，嫁女今无王右军。",
            "借问琴书终一世，何如旗盖仰三分。",
            "代北偏师衔使节，关中裨将建行台。",
            "不妨常日饶轻薄，且喜临戎用草莱。",
            "郭令素心非黩武，韩公本意在和戎。",
            "两都耆旧偏垂泪，临老中原见朔风。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 417. 射鱼曲 ----------
    {
        "id": "li-shang-yin-417",
        "title": "射鱼曲",
        "author": "李商隐",
        "poet_id": "li-shang-yin",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷198》",
        "verse": [
            "思牢弩箭磨青石，绣额蛮渠三虎力。寻潮背日伺泅鳞，",
            "贝阙夜移鲸失色。纤纤粉簳馨香饵，绿鸭回塘养龙水。",
            "含冰汉语远于天，何由回作金盘死。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
