    # ---------- 440. 摇落 ----------
    {
        "id": "li-shang-yin-440",
        "title": "摇落",
        "author": "李商隐",
        "poet_id": "li-shang-yin",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷3》",
        "verse": [
            "摇落伤年日，羁留念远心。水亭吟断续，月幌梦飞沉。",
            "古木含风久，疏萤怯露深。人闲始遥夜，地迥更清砧。",
            "结爱曾伤晚，端忧复至今。未谙沧海路，何处玉山岑。",
            "滩激黄牛暮，云屯白帝阴。遥知沾洒意，不减欲分襟。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
