            "曾共山翁把酒时，霜天白菊绕阶墀。十年泉下无人问，",
            "九日樽前有所思。不学汉臣栽苜蓿，空教楚客咏江蓠。",
            "郎君官贵施行马，东阁无因再得窥。",
